import{_ as t,o as s,c as a,a5 as i}from"./chunks/framework.B1nibuwM.js";const u=JSON.parse('{"title":"Testing","description":"","frontmatter":{},"headers":[],"relativePath":"dev/testing.md","filePath":"dev/testing.md"}'),o={name:"dev/testing.md"};function r(n,e,d,c,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><p>Conventions and helpers for the test suite.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                            # the whole suite</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CompilerTest</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # a single class</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> performance</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # perf tests, excluded from the default run</span></span></code></pre></div><p><code>composer test</code> runs tests only. Code style is <code>composer lint</code> and static analysis is <code>composer analyse</code> — each command does one thing, matching how CI runs them.</p><h2 id="prefer-data-providers" tabindex="-1">Prefer data providers <a class="header-anchor" href="#prefer-data-providers" aria-label="Permalink to &quot;Prefer data providers&quot;">​</a></h2><p>Most behavior in this library varies along a few axes — OpenAPI version, processing mode, annotation vs attribute vs spec input. Repeating a test body per combination gets long and hides which case actually failed.</p><p>Use <code>#[DataProvider]</code> and let the provider name the case, so a failure reports <em>which</em> combination broke rather than just the assertion. Most of the suite already works this way; follow the closest existing example rather than inventing a new shape.</p><p>Prefer adding a case to an existing provider over copying a whole test method. Prefer adding new test cases over modifying existing ones — an existing case usually encodes a regression somebody cared about.</p><h3 id="build-objects-in-the-test-not-in-the-provider" tabindex="-1">Build objects in the test, not in the provider <a class="header-anchor" href="#build-objects-in-the-test-not-in-the-provider" aria-label="Permalink to &quot;Build objects in the test, not in the provider&quot;">​</a></h3><p>PHPUnit evaluates providers while collecting tests, before coverage recording starts, so anything constructed in a provider is <strong>asserted but never counted as covered</strong>. Yield class names and arguments; construct in the test body.</p><p>The failure is silent — tests pass either way — and only shows up when someone runs coverage and wonders why a tested class reads as untouched.</p><h2 id="prefer-a-fixture-to-an-assertion" tabindex="-1">Prefer a fixture to an assertion <a class="header-anchor" href="#prefer-a-fixture-to-an-assertion" aria-label="Permalink to &quot;Prefer a fixture to an assertion&quot;">​</a></h2><p>A test that asserts what the implementation currently produces captures the status quo. That is worth having, but it is not evidence the output is <em>correct</em> — it only pins today&#39;s behaviour so tomorrow&#39;s change is visible.</p><p>Where the output is a specification document, a scratch fixture is stronger. It runs the whole pipeline rather than one stage, it produces a file per OpenAPI version, and those files are linted by <code>composer redocly</code> against the real schema. The expectation then comes from the specification rather than from whoever wrote the test.</p><p>Concretely: the attributes now covered by <code>Fixtures/Scratch/Auth-spec.php</code> were first covered by a unit test asserting compiler output. Every case passed. The fixture that replaced it immediately failed Redocly, because the pipeline was emitting <code>type: mutualTLS</code> into OpenAPI 3.0 documents, where that type does not exist. The assertions had faithfully encoded the bug.</p><p>Reach for a unit test when there is no document to validate — <code>ComponentIndexTest</code> and <code>SlotMapConsistencyTest</code> are the right shape, because neither has a YAML counterpart.</p><h2 id="shared-helpers" tabindex="-1">Shared helpers <a class="header-anchor" href="#shared-helpers" aria-label="Permalink to &quot;Shared helpers&quot;">​</a></h2><p><code>tests/Concerns/</code> holds the reusable pieces. Look here before writing setup code:</p><table tabindex="0"><thead><tr><th>Trait</th><th>Use for</th></tr></thead><tbody><tr><td><code>AssemblesSpecification</code></td><td><code>assemble(...$classes)</code> — build a <code>Specification</code> from classes without touching the filesystem</td></tr><tr><td><code>AssertsBuilderResult</code></td><td>asserting on a <code>Builder\\Result</code>, including expected warnings and errors</td></tr><tr><td><code>AssertsSchemaStructure</code></td><td>comparing compiled schema structure (<code>allOf</code> refs + property names) against a YAML fixture, independent of property order</td></tr><tr><td><code>CollectsSpecClasses</code></td><td>enumerating every <code>OpenApi\\Spec</code> attribute class, for suite-wide invariants</td></tr><tr><td><code>GeneratesTestMatrix</code></td><td>building version × mode combinations, with exclusions, and discovering fixtures by glob</td></tr><tr><td><code>UsesExamples</code></td><td>registering a classloader for a <code>docs/examples</code> implementation</td></tr></tbody></table><p><code>GeneratesTestMatrix</code> is the one to reach for when a test needs to run across versions and modes — it handles the cartesian product, the exclusions, and stable test-case naming, so providers stay short.</p><p><code>SlotMapConsistencyTest</code> is a good example of the suite-wide-invariant style: rather than testing one attribute, it checks a property that must hold across all of them.</p><h2 id="the-docs-are-part-of-the-test-suite" tabindex="-1">The docs are part of the test suite <a class="header-anchor" href="#the-docs-are-part-of-the-test-suite" aria-label="Permalink to &quot;The docs are part of the test suite&quot;">​</a></h2><p>Two tests verify documentation against real output. Both will fail if you add documentation without its counterpart:</p><p><strong><code>DocSnippetsTest</code></strong> runs every <code>docs/snippets/*_an.php</code> and compares against the matching <code>-3.1.0.yaml</code>, across the applicable modes and implementations. Adding a snippet means adding <em>all</em> of:</p><ul><li><code>foo_an.php</code> (annotations), <code>foo_at.php</code> (attributes), <code>foo_spec.php</code> (spec attributes)</li><li><code>foo-3.1.0.yaml</code> — the expected output</li></ul><p>Missing implementations are skipped rather than failing, but a missing or stale <code>-3.1.0.yaml</code> is a failure. The mode/implementation pairing is deliberate: spec mode runs only spec snippets and classic mode never runs them, but hybrid runs all three.</p><p><strong><code>ExamplesTest</code></strong> does the same for <code>docs/examples/specs/*</code>, against the per-version <code>*-3.0.0.yaml</code> / <code>*-3.1.0.yaml</code> / <code>*-3.2.0.yaml</code> fixtures.</p><p>This is why changing pipeline output shows up as a wall of documentation failures. That is the suite working: the expected YAML files are the specification of what the pipeline produces, and they are what the published docs display.</p><h2 id="fixtures" tabindex="-1">Fixtures <a class="header-anchor" href="#fixtures" aria-label="Permalink to &quot;Fixtures&quot;">​</a></h2><ul><li><code>tests/Fixtures/</code> — general test fixtures</li><li><code>tests/Fixtures/Scratch/</code> — spec-pipeline scratch fixtures with expected YAML, exercised by <code>ScratchTest</code></li><li><code>docs/examples/specs/</code> — full worked examples, doubling as published documentation</li></ul><p><code>composer redocly</code> validates the generated example specs against the OpenAPI schema. It passes, with warnings; known problems are suppressed via <code>.redocly.lint-ignore.yaml</code>, so a <em>new</em> failure means something genuinely regressed.</p>`,31)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
